head.script:
scwin.gVar = {
    "cStyle" : "",
    "cStyleParent" : "",
}



scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제 (target1 은 parent1 하위에 생성되므로 parent1 삭제로 함께 제거)
    if (typeof parent1 !== 'undefined') {
        parent1.remove();
    }

    // 조건 설정
    //  ※ base(common_M_getPosition_1) 는 style(target) / style(parent) 두 조건을 전달하므로
    //    createBasicWidgetContainer(고정 style, parent 그룹 없음) 로는 검증이 불가하다.
    //    -> parent1 그룹을 만들어 style(parent) 를 적용하고, widgetContainer 는 직접 dynamicCreate 하여
    //       style(target) 조건값을 반영한다. (offsetParent 기준 좌표 계산 확인 목적)
    let cStyle = scwin.gVar["cStyle"];
    cStyle += "width:300px; height:200px;";
    let cStyleParent = scwin.gVar["cStyleParent"];

    // parent 생성
    let grp_comp = $c.gcm.getTestGroup();

    let strNameSpace = $c.gcm.getNameSpace();

    let strParent = '';
    strParent += '<xf:group ' + strNameSpace + ' style="background-color:var(--ws-green-100); height: 400px; '+cStyleParent+'">';
    strParent += '</xf:group>';

    scwin.parent1 = await $p.dynamicCreate(
        "parent1",
        "group",
        strParent,
        grp_comp
    );

    let strTarget = '';
    strTarget += '<w2:widgetContainer ' + strNameSpace + ' mode="" cols="" style="' + cStyle + '"></w2:widgetContainer>';

    // base(common_M)가 objParent.target1 로 접근하므로 target1 id 로 생성 (parent1 하위에 생성)
    scwin.target1 = await $p.dynamicCreate('target1', "widgetContainer", strTarget, parent1);

    // 내용 확인용 Widget 1개 추가 (Widget 이 없으면 Container 내용이 비어 확인 불가)
    let addedWidgets = scwin.target1.addWidgets({
        id : "widget1",
        title : "위젯01",
        src : "/sample/common_link/widgetContainer_link_1.xml",
        scope : true,
        unitWidth : 1,
        unitHeight : 1
    });

    // 추가한 Widget 을 최대화 (maxConfig 미설정이므로 Container 크기만큼 확장)
    if (addedWidgets && addedWidgets[0]) {
        addedWidgets[0].setMaximized();
    }
}
